using System;using System.Text;using System.Diagnostics;using LoopFive;
class ResearchDspTests {
 static int count;static void A(bool b,string s){if(!b)throw new Exception(s);count++;Console.WriteLine("PASS "+s);}
 static FxConfig Config(string t){return new FxConfig{Type=t,On=true,Detailed=true,Mix=1,Amount=.5f,Rate=.2f,Feedback=.2f,Detail=new FxDetail()};}
 static float[] Run(FxConfig c,int n,Func<int,float> source){FxProcessor p=new FxProcessor();p.Prepare(c,120,60,true);float[] result=new float[n];for(int i=0;i<n;i++){float l=source(i),r=l;p.Tick(ref l,ref r,i/22050.0);result[i]=l;}return result;}
 static double Energy(float[] x,int a,int b){double e=0;for(int i=a;i<b;i++)e+=x[i]*x[i];return e;}
 static Engine Clean(){Engine e=new Engine();e.Config.Master=1;e.Config.Limiter=false;e.Config.Quantize=false;e.Config.Rhythm.Enabled=false;e.Config.InputFx.Enabled=false;e.Config.TrackFx.Enabled=false;return e;}
 static void Main(){try{
 FxConfig c=Config("LO-FI");c.Detail.Bits=3;c.Detail.SampleDivisor=4;float[] crushed=Run(c,4096,delegate(int i){return (float)Math.Sin(i*.17)*.8f;});System.Collections.Generic.HashSet<float> levels=new System.Collections.Generic.HashSet<float>(crushed);A(levels.Count<=9,"LO-FI bit depth produces a bounded number of quantization levels");bool held=true;for(int i=0;i<crushed.Length;i+=4)for(int j=1;j<4;j++)held&=crushed[i]==crushed[i+j];A(held,"LO-FI sample-rate reduction holds exactly the configured interval");
 c=Config("DELAY");c.Detail.TimeMs=100;c.Feedback=0;float[] delay=Run(c,10000,delegate(int i){return i==0?1:0;});A(Energy(delay,0,4409)==0&&Math.Abs(delay[4410]-1)<.0001,"delay uses the requested millisecond time without early echoes");
 c=Config("DELAY");c.Sync=true;c.Beats=2;c.Feedback=0;FxProcessor longDelay=new FxProcessor();longDelay.Prepare(c,40,60,true);bool early=false;float longEcho=0;for(int i=0;i<=132300;i++){float l=i==0?1:0,r=l;longDelay.Tick(ref l,ref r,i/66150.0);if(i<132299&&Math.Abs(l)>.00001)early=true;if(i==132300)longEcho=l;}A(!early&&Math.Abs(longEcho-1)<.0001,"long tempo-synced delay uses 3 seconds instead of silently clipping at the old buffer limit");
 c=Config("EQ");float[] eq=Run(c,4096,delegate(int i){return (float)Math.Sin(i*.2)*.2f;});double error=0;for(int i=0;i<eq.Length;i++)error=Math.Max(error,Math.Abs(eq[i]-(float)Math.Sin(i*.2)*.2f));A(error<1e-6,"four-region EQ at zero dB reconstructs input without coloration");
 c=Config("FREEZE");FxProcessor freeze=new FxProcessor();freeze.Prepare(c,120,60,true);double sustained=0;for(int i=0;i<15000;i++){float l=i<4096?(float)Math.Sin(i*.13)*.2f:0,r=l;freeze.Tick(ref l,ref r,i/22050.0);if(i>9000)sustained+=l*l;}A(sustained>1,"FREEZE sustains the captured texture after the live input stops");c.On=false;freeze.Prepare(c,120,60,true);double first=0,last=0;for(int i=0;i<50000;i++){float l=0,r=0;freeze.Tick(ref l,ref r,1+i/22050.0);if(i<1000)first+=l*l;if(i>49000)last+=l*l;}A(first>0&&last<first*.00001,"FREEZE release fades its tail instead of an immediate hard cut");
 c=Config("TREMOLO");c.Detail.Depth=0;c.Sequence=true;c.Steps=2;c.Beats=.5f;c.SequenceValues[0]=0;c.SequenceValues[1]=1;float[] seq=Run(c,22050,delegate(int i){return .2f;});A(Energy(seq,0,10000)==0&&Energy(seq,12000,22000)>1,"detailed level sequence follows musical step boundaries");
 Engine e=Clean();e.Config.InputFx.Enabled=true;e.Config.Monitor=true;float[] carrier=new float[44100];for(int i=0;i<carrier.Length;i++)carrier[i]=(float)(i%101/50.0-1)*.2f;e.Import(0,new AudioClip(carrier,(float[])carrier.Clone(),120,2));e.Tracks[0].Config.Level=0;e.Play(0);e.Config.InputFx.Slots[0]=Config("VOCODER");e.Config.InputFx.Slots[0].Detail.Carrier=0;float[] input=new float[1024],output=new float[1024];double vocEnergy=0;for(int block=0;block<30;block++){for(int i=0;i<512;i++)input[i*2]=input[i*2+1]=(float)Math.Sin((block*512+i)*.07)*.3f;e.Process(input,output,512);foreach(float x in output)vocEnergy+=x*x;}A(vocEnergy>.001,"VOCODER uses a playing carrier track even when its fader is at zero");e.Config.InputFx.Slots[0].Detail.Carrier=1;e.ResetDsp();double empty=0;for(int block=0;block<4;block++){e.Process(input,output,512);foreach(float x in output)empty+=x*x;}A(empty==0,"empty VOCODER carrier produces silence at 100 percent wet");
 e=Clean();e.Config.TrackFx.Enabled=true;for(int i=0;i<3;i++){float[] audio=new float[1024];for(int j=0;j<audio.Length;j++)audio[j]=.1f*(i+1);e.Import(i,new AudioClip(audio,(float[])audio.Clone(),120,1));e.Tracks[i].Config.Level=1;e.Play(i);}c=Config("DELAY");c.Detail.InsertMask=1;c.Detail.TimeMs=100;e.Config.TrackFx.Slots[0]=c;c=Config("MANUAL PAN");c.Amount=1;c.Detail.InsertMask=2;e.Config.TrackFx.Slots[1]=c;e.Process(null,output,1);A(Math.Abs(output[0]-.3f)<.0001&&Math.Abs(output[1]-.5f)<.0001,"separate slot inserts affect only their selected tracks and leave the third dry");
 FxConfig cloned=Storage.Clone(e.Config.TrackFx.Slots[0]);A(cloned.Detailed&&cloned.Detail.InsertMask==1&&cloned.Detail.TimeMs==100,"detailed parameters and slot routing survive serialization");FxConfig old=Storage.FromJson<FxConfig>(Encoding.UTF8.GetBytes("{\"Type\":\"DELAY\",\"On\":false}"));A(!old.Detailed,"older effect settings keep legacy processing mode");
 Stopwatch watch=Stopwatch.StartNew();foreach(string type in FxCatalog.All){c=Config(type);c.Detail.Carrier=5;FxProcessor p=new FxProcessor();p.CarrierL=new float[7];p.CarrierR=new float[7];p.Prepare(c,120,60,true);double energy=0;for(int i=0;i<44100;i++){float l=(float)Math.Sin(i*.07)*.2f,r=(float)Math.Sin(i*.1)*.15f;p.CarrierL[5]=p.CarrierR[5]=(float)Math.Sin(i*.11)*.4f;p.Tick(ref l,ref r,i/22050.0);if(float.IsNaN(l)||float.IsInfinity(l)||Math.Abs(l)>16)throw new Exception("Unstable detailed effect "+type);energy+=l*l+r*r;}A(energy>1e-8,"detailed effect renders finite audible output: "+type);}Console.WriteLine("All detailed effect renders: "+watch.ElapsedMilliseconds+" ms");
 Console.WriteLine("TOTAL "+count+" research DSP checks passed");}catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
}
